#include <stdio.h>
#include <string.h>
int main() {
    char s1[1000], s2[1000];
    if (scanf("%s %s", s1, s2) == 2) {
        if (strlen(s1) == strlen(s2)) {
            char double_s1[2000];
            strcpy(double_s1, s1); strcat(double_s1, s1);
            if (strstr(double_s1, s2)) { puts("Yes"); return 0; }
        }
        puts("No");
    }
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    string s1, s2;
    if (cin >> s1 >> s2) {
        if (s1.length() == s2.length() && (s1 + s1).find(s2) != string::npos) {
            cout << "Yes\n";
        } else {
            cout << "No\n";
        }
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s1 = sc.next(), s2 = sc.next();
            if (s1.length() == s2.length() && (s1 + s1).contains(s2)) System.out.println("Yes");
            else System.out.println("No");
        }
    }
}

