const fs = require("fs");
function main() {
    const lines = fs.readFileSync(0, "utf-8").split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    if (lines.length >= 2) {
        const s1 = lines[0], s2 = lines[1];
        console.log((s1.length === s2.length && (s1 + s1).includes(s2)) ? "Yes" : "No");
    }
}
main();

